create table public.group_period_stats (group_id uuid, period_type text, period_start date, member_count integer default 0, active_members integer default 0, group_score bigint default 0, eligible boolean default false, top_contributors jsonb default '[]'::jsonb, updated_at timestamp with time zone default now());
