create table public.player_game_period_stats (user_id uuid, game_id text, period_type text, period_start date, games_played integer default 0, total_score bigint default 0, best_score integer, total_correct integer default 0, total_questions integer default 0, average_accuracy numeric(5,2), best_daily_points integer default 0, metric_name text, best_metric_value numeric, updated_at timestamp with time zone default now());
create table public.player_period_stats (user_id uuid, period_type text, period_start date, games_played integer default 0, questions_answered bigint default 0, daily_brain_score integer default 0, full_daily_count integer default 0, active_days integer default 0, xp_earned bigint default 0, updated_at timestamp with time zone default now());
create table public.player_personal_bests (user_id uuid, game_id text, result_id uuid, metric_name text, metric_value numeric, score integer, correct_answers integer, total_questions integer, accuracy numeric(5,2), duration_ms integer, result_payload jsonb default '{}'::jsonb, achieved_at timestamp with time zone, updated_at timestamp with time zone default now());
create table public.player_progression (user_id uuid, current_streak integer default 0, best_streak integer default 0, full_daily_count integer default 0, xp bigint default 0, level integer default 1, total_games integer default 0, total_questions bigint default 0, favorite_game_id text, last_streak_date date, last_active_at timestamp with time zone, updated_at timestamp with time zone default now());
